button.onclick=()=>show('combatLabScreen');el('labBack').onclick=()=>show('menuScreen');el('labDirection').onchange=()=>run(()=>{plan.direction=Number(el('labDirection').value);if(session)session.e.gridDirection=plan.direction;draw();});for(const id of ['labHearing','labSight'])el(id).onchange=()=>run(()=>{const hearing=Number(el('labHearing').value),sight=Number(el('labSight').value);if(!Number.isInteger(hearing)||hearing<1||hearing>10||!Number.isInteger(sight)||sight<1||sight>20)throw Error('ระยะได้ยิน 1–10 / มอง 1–20');plan.senses={hearing,sight};if(session){session.e.units[0].hearingRange=hearing;session.e.units[0].sightRange=sight;}draw();});for(const [id,name]of Object.entries(N.classes))el('labJob').add(new Option(name.name,id));el('labJob').onchange=()=>{plan.job=el('labJob').value;plan.weapon=N.classes[plan.job].starter[0];weapons();draw();};el('labWeapon').onchange=()=>plan.weapon=el('labWeapon').value;el('labAbility').onchange=()=>{plan.action=el('labAbility').value;draw();};el('labLoadPreset').onclick=()=>run(()=>setup(el('labPreset').value));el('labStart').onclick=()=>run(start);el('labRestart').onclick=()=>run(start);el('labEdit').onclick=()=>{session=null;notice('จัดสนามได้แล้ว • ผลต่อสู้เดิมถูกล้างเมื่อเริ่มใหม่');draw();};el('labUse').onclick=()=>run(()=>L.act(session,el('labAbility').value,selected,selectedTargets.size?[...selectedTargets]:undefined));el('labMove').onclick=()=>run(()=>C.move(session.e,D.node(selected)));el('labEnd').onclick=()=>run(()=>L.endTurn(session));el('labRefill').onclick=()=>run(()=>L.refill(session));el('labCancelCast').onclick=()=>run(()=>C.cancelCast(session.e));el('labApplyCell').onclick=()=>run(()=>{const x=Number(el('labX').value)-1,y=Number(el('labY').value)-1;if(!Number.isInteger(x)||x<0||x>=12||!Number.isInteger(y)||y<0||y>=10)throw Error('X 1–12 / Y 1–10');editCell(y*12+x);});
const canvas=el('labCanvas');canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false};canvas.setPointerCapture(e.pointerId);canvas.focus({preventScroll:true});};canvas.onpointermove=e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>6)drag.moved=true;if(drag.moved)view.pan(e.clientX-drag.lastX,e.clientY-drag.lastY);drag.lastX=e.clientX;drag.lastY=e.clientY;};canvas.onpointerup=e=>{if(!drag)return;const moved=drag.moved;drag=null;if(!moved){const r=canvas.getBoundingClientRect(),i=view.pick(session?.e.scene||plan.scene,e.clientX-r.left,e.clientY-r.top);if(i!==null)run(()=>editCell(i));}};canvas.onpointercancel=()=>drag=null;canvas.addEventListener('wheel',e=>{e.preventDefault();const r=canvas.getBoundingClientRect();view.zoom(e.deltaY<0?1.12:1/1.12,e.clientX-r.left,e.clientY-r.top);},{passive:false});canvas.onkeydown=e=>{let i=selected;if(e.key==='ArrowLeft'&&i%12>0)i--;else if(e.key==='ArrowRight'&&i%12<11)i++;else if(e.key==='ArrowUp'&&i>=12)i-=12;else if(e.key==='ArrowDown'&&i<108)i+=12;else if(e.key==='Enter'){e.preventDefault();run(()=>editCell(i));return;}else return;e.preventDefault();selected=i;draw();};el('labZoomIn').onclick=()=>view.zoom(1.2);el('labZoomOut').onclick=()=>view.zoom(1/1.2);el('labFit').onclick=()=>view.fit(session?.e.scene||plan.scene);new ResizeObserver(()=>{if(!section.hidden)draw();}).observe(canvas);
window.DecideCombatLab={open,reset(){session=null;plan=null;drag=null;},cellPoint(x,y){return view.cellPoint(session?.e.scene||plan.scene,y*12+x);},snapshot(){return {plan:plan&&JSON.parse(JSON.stringify(plan)),session:session&&JSON.parse(JSON.stringify(session))};}};
